function retryImport(factory, retries = 3, delay = 500) {
  return new Promise((resolve, reject) => {
    factory()
      .then(resolve)
      .catch(err => {
        if (retries <= 0) {
          reject(err);
          return;
        }
        setTimeout(() => {
          retryImport(factory, retries - 1, delay).then(resolve, reject);
        }, delay);
      });
  });
}

const Profile = React.lazy(() => retryImport(() => import('./Profile')));

function App() {
  return (
    <React.Suspense fallback={<p>Loading…</p>}>
      <Profile />
    </React.Suspense>
  );
}
